// Draw spiral
const centerX = W / 2;
const centerY = H / 2;
const maxRadius = Math.min(W, H) / 2 - 20;

function drawSpiral(radius, angle, depth) {
    if (depth > 10) return;

    // Calculate new position
    const x = centerX + Math.cos(angle) * radius;
    const y = centerY + Math.sin(angle) * radius;

    // Draw line segment
    ctx.strokeStyle = `hsl(${200 - depth * 10}, 80%, ${80 - depth * 10}%)`;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(centerX, centerY);
    ctx.lineTo(x, y);
    ctx.stroke();

    // Recursive call for next segment
    const nextRadius = radius + 10;
    const nextAngle = angle + 0.3;
    drawSpiral(nextRadius, nextAngle, depth + 1);
}

